import{_ as a,o as t,c as n,a3 as l}from"./chunks/framework.z_KJ15Ep.js";const r="/bilder/unterricht-kataloge/kataloge-schulbez-1.png",f=JSON.parse('{"title":"Schulbezogene Kataloge aufrufen","description":"","frontmatter":{"title":"Schulbezogene Kataloge aufrufen","source_pageid":452,"source_revision":5427},"headers":[],"relativePath":"schild3/unterricht-kataloge/schulbezogene-kataloge-kataloge.md","filePath":"schild3/unterricht-kataloge/schulbezogene-kataloge-kataloge.md"}'),o={name:"schild3/unterricht-kataloge/schulbezogene-kataloge-kataloge.md"};function i(g,e,s,u,c,h){return t(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="schulbezogene-kataloge-aufrufen" tabindex="-1">Schulbezogene Kataloge aufrufen <a class="header-anchor" href="#schulbezogene-kataloge-aufrufen" aria-label="Permalink to &quot;Schulbezogene Kataloge aufrufen&quot;">​</a></h1><p>Finden Sie die Kataloge für die schulinterne Organisation. Ihre Bedienung folgt den gemeinsamen Funktionen für Reihenfolge, Sichtbarkeit und Bearbeitung von Einträgen.</p><p><a href="/bilder/unterricht-kataloge/kataloge-schulbez-1.png"><img src="'+r+'" alt="Schulbezogene Kataloge" loading="lazy"></a></p><p><em>Schulbezogene Kataloge</em></p><p>Die schulbezogenen Listen öffnen Sie über den Reiter <strong>Kataloge</strong>. Dazu gehören zum Beispiel Unterrichtsfächer, Jahrgänge, Klassen, Kurse und schulinterne Funktionen.</p><p>Die Steuerung der Kataloge, also das Festlegen der Reihenfolge der Einträge, der Sichtbarkeit usw., ist analog zu den allgemeinen Katalogen.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Schulbezogene_Kataloge_(Kataloge)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5427.</p>',8)])])}const p=a(o,[["render",i]]);export{f as __pageData,p as default};
